import icontract
from typing import List


@icontract.ensure(lambda a, b, result: len(result) == len(a) + len(b))
@icontract.ensure(lambda a, result: all(result[k] == a[k] for k in range(len(a))))
@icontract.ensure(lambda a, b, result: all(result[k + len(a)] == b[k] for k in range(len(b))))
def concat(a: List[int], b: List[int]) -> List[int]:
    out = []
    for x in a:
        out.append(x)
    for x in b:
        out.append(x)
    return out
